import numpy as np
def solve(g):
    g=np.array(g); H,W=g.shape
    cnt=np.bincount(g.flatten()); bg=int(cnt.argmax())
    vals,counts=np.unique(g,return_counts=True)
    block=[int(v) for v,c in zip(vals,counts) if c==max(counts)][0]
    rs,cs=np.where(g==block); r0,r1,c0,c1=rs.min(),rs.max(),cs.min(),cs.max()
    out=g.copy()
    for r in range(H):
        for c in range(W):
            m=g[r,c]
            if m in (bg,block): continue
            # nearest block cell sharing row or column, minimize manhattan among valid same-row/same-col candidates
            best=None
            for rr in range(r0,r1+1):
                for cc in range(c0,c1+1):
                    if g[rr,cc]!=block: continue
                    d=abs(rr-r)+abs(cc-c)
                    if best is None or d<best[0]: best=(d,rr,cc)
            if best: out[best[1],best[2]]=m
    return out.tolist()
